// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(uint256 amount, uint256 amount2, address ownerAddr) public {
        vm.assume(ownerAddr != address(0));

        c.AdjustBetAmounts(amount);

        c.AdjustDifficulty(amount2);

        bool ok = (c.currentBetLimit() == amount) && (c.currentDifficulty() == amount2);
        assertTrue(ok);
    }
}
